export type ArcId = "disc-1" | "disc-2" | "disc-3" | "disc-4";

export type CoverageState = "planned" | "partial" | "implemented-unverified" | "verified";

export type GuideArea = {
  id: string;
  title: string;
  arcId: ArcId;
  state: CoverageState;
};

type ArcArea = { id: string; title: string };

const area = (id: string, title: string): ArcArea => ({ id, title });

