    nextAvailability: "No later replay route for this ATE chain is documented. The two prior-scene conditions must be met in their earlier story windows.",
    action: "At Blank's Guest Room prompt, choose “Where's Dagger?”; view Something Washed Ashore if available, then travel to the telescope and speak with Dagger for My Bad. Something Washed Ashore requires Hallucination in Treno. View the Cid-meeting and My Hammer scenes, then enter the Theater District to trigger The Rally automatically if Wei and Kal's Burmecia scene was viewed. Leave the three Tantalus Gil chests unopened; get below 50 Gil before delivering the potions; leave the Royal Chamber for No Free Lunch, visit the Business District pickle seller with Quina, and board the Blue Narciss for Give Me My Money. Return to the chests only after the ATE has triggered.",
    recovery: "After the ship departure, no same-save route to replay these ATEs is documented. Reload a save from before leaving Lindblum or view the missed events in another playthrough. The chapter does not imply that an unavailable prior-condition ATE can be created here.",
    note: "GameFAQs, Jegged, and Gamer Guides specify fewer than 50 Gil, the No Free Lunch chamber-exit prompt, the separate pickle-seller setup scene, and the Blue Narciss ATE; an older Deis' Discs route says below 100 Gil. The route uses under 50 as the conservative threshold. The Rally and Something Washed Ashore have distinct prior-story prerequisites. Movie Critic platform mapping is complete for Steam, PS4, and Xbox; mobile service parity remains unresolved.",
